describe('Notifications Empty State', () => {
  beforeEach(() => {
    cy.visit('/notifications');
    cy.intercept('GET', '**/api/notifications', { body: [] }).as('getNotifications');
    cy.wait('@getNotifications');
  });

  it('should display empty state message when user has no notifications', () => {
    cy.get('[data-testid="empty-state-container"]').should('be.visible');
    cy.get('[data-testid="empty-state-title"]').should('contain', 'No notifications');
    cy.get('[data-testid="empty-state-description"]').should('contain', 'You\'re all caught up');
    cy.get('[data-testid="empty-state-icon"]').should('be.visible');
  });

  it('should display empty state with correct styling and layout', () => {
    cy.get('[data-testid="empty-state-container"]').should('have.css', 'display', 'flex');
    cy.get('[data-testid="empty-state-container"]').should('have.css', 'justify-content', 'center');
    cy.get('[data-testid="empty-state-container"]').should('have.css', 'align-items', 'center');
    cy.get('[data-testid="empty-state-icon"]').should('be.visible');
    cy.get('[data-testid="empty-state-title"]').should('be.visible');
    cy.get('[data-testid="empty-state-description"]').should('be.visible');
  });

  it('should not display notification list when empty', () => {
    cy.get('[data-testid="notifications-list"]').should('not.exist');
  });

  it('should handle network error gracefully and show empty state', () => {
    cy.intercept('GET', '**/api/notifications', { statusCode: 500 }).as('getNotificationsError');
    cy.visit('/notifications');
    cy.wait('@getNotificationsError');
    cy.get('[data-testid="empty-state-container"]').should('be.visible');
  });

  it('should transition from empty state when notification is added', () => {
    cy.get('[data-testid="empty-state-container"]').should('be.visible');
    cy.intercept('GET', '**/api/notifications', {
      body: [{ id: 1, message: 'New notification', read: false }]
    }).as('getNotificationsUpdated');
    cy.get('[data-testid="refresh-button"]').click();
    cy.wait('@getNotificationsUpdated');
    cy.get('[data-testid="empty-state-container"]').should('not.exist');
    cy.get('[data-testid="notifications-list"]').should('be.visible');
  });
});
